package me.cobbleBet.connections.listeners;
import com.google.gson.JsonObject;import me.cobbleBet.Main;import me.cobbleBet.connections.*;import org.bukkit.*;import org.bukkit.entity.Player;import java.util.UUID;
public final class SocketDepositRequestListener extends SocketMessageListener{
 public SocketDepositRequestListener(String type,CobbleSocketClient client){super(type,client);} @Override public void trigger(JsonObject json){Bukkit.getScheduler().runTask(Main.getInstance(),()->{JsonObject out=new JsonObject();out.addProperty("type","depositResult");out.addProperty("requestId",json.has("requestId")?json.get("requestId").getAsString():"");try{Player player=Bukkit.getPlayer(UUID.fromString(json.get("playerUUID").getAsString()));double amount=json.get("amount").getAsDouble();String source=json.has("source")?json.get("source").getAsString():"inventory";if(player==null)throw new IllegalStateException("You must be online in the game server to deposit.");boolean success=source.equals("ender_chest")?Main.getInstance().getEconomyManager().depositFromEnderChest(player,amount):Main.getInstance().getEconomyManager().deposit(player,amount);if(!success)throw new IllegalStateException(Main.economyType.equalsIgnoreCase("item")?"Not enough configured items in that location.":"The server economy could not complete the deposit.");out.addProperty("success",true);out.addProperty("amount",amount);out.addProperty("balance",Main.getInstance().getEconomyManager().getBalance(player));}catch(Exception error){out.addProperty("success",false);out.addProperty("message",error.getMessage()==null?"Deposit failed.":error.getMessage());}if(client.isOpen())client.send(out.toString());});}}
